import 'dart:math' as math;

import 'package:lazerus_core/lazerus_core.dart';

/// One transient spectrum snapshot for the Multiband EQ inspector.
///
/// It is deliberately owned by the EQ presentation module: visual frequency
/// analysis is neither a Macro runtime concern nor part of the persisted graph
/// contract.
final class MultibandEqSpectrum {
  MultibandEqSpectrum({
    required Iterable<double> frequenciesHz,
    required Iterable<double> levels,
    required this.sampleRateHz,
  }) : frequenciesHz = List<double>.unmodifiable(frequenciesHz),
       levels = List<double>.unmodifiable(levels) {
    if (this.frequenciesHz.length != this.levels.length) {
      throw ArgumentError(
        'Spectrum frequencies and levels must have the same length.',
      );
    }
  }

  final List<double> frequenciesHz;
  final List<double> levels;
  final int sampleRateHz;
}

/// Bounded, display-only analysis for the Multiband EQ node.
///
/// PCM is supplied through [TriggerMonoAudioValue], whose non-null
/// [TriggerMonoAudioValue.sampleRateHz] keeps the frequency axis correct for
/// every transport or capture implementation. This analyzer never feeds the
/// runtime EQ outputs and retains no PCM after [analyze] returns.
final class MultibandEqSpectrumAnalyzer {
  const MultibandEqSpectrumAnalyzer();

  // At 44.1 kHz, this provides approximately 21.5 Hz frequency-bin
  // resolution when the capture frame supplies the full window.
  static const _maximumFrameSize = 2048;
  // Log-spaced points give high frequencies useful visual detail without an
  // unbounded amount of per-frame Goertzel work.
  static const _maximumBars = 256;

  MultibandEqSpectrum analyze(TriggerMonoAudioValue audio) {
    final samples = audio.values;
    // A two-point Hann window has no non-zero samples, so it cannot produce a
    // meaningful normalized spectrum. The microphone meter remains separate.
    if (samples.length < 3) {
      return MultibandEqSpectrum(
        frequenciesHz: const <double>[],
        levels: const <double>[],
        sampleRateHz: audio.sampleRateHz,
      );
    }

    final frameSize = math.min(samples.length, _maximumFrameSize);
    final maximumBin = frameSize ~/ 2;
    final binNumbers = <int>{};
    for (var index = 0; index < _maximumBars; index++) {
      final fraction = _maximumBars == 1 ? 0.0 : index / (_maximumBars - 1);
      final bin = math.pow(maximumBin, fraction).round().clamp(1, maximumBin);
      binNumbers.add(bin.toInt());
    }
    final bins = binNumbers.toList()..sort();

    var windowSum = 0.0;
    final windowed = List<double>.generate(frameSize, (index) {
      final window =
          0.5 - 0.5 * math.cos((2 * math.pi * index) / (frameSize - 1));
      windowSum += window;
      return samples[index] * window;
    }, growable: false);

    final frequencies = <double>[];
    final levels = <double>[];
    for (final bin in bins) {
      // Goertzel gives the relevant single-bin DFT magnitude while avoiding a
      // trigonometric call for every source sample and visual bar.
      final coefficient = 2 * math.cos((2 * math.pi * bin) / frameSize);
      var previous = 0.0;
      var previousPrevious = 0.0;
      for (final sample in windowed) {
        final next = sample + coefficient * previous - previousPrevious;
        previousPrevious = previous;
        previous = next;
      }
      final power = math.max(
        0.0,
        previousPrevious * previousPrevious +
            previous * previous -
            coefficient * previous * previousPrevious,
      );
      frequencies.add(bin * audio.sampleRateHz / frameSize);
      levels.add((2 * math.sqrt(power) / windowSum).clamp(0.0, 1.0).toDouble());
    }

    return MultibandEqSpectrum(
      frequenciesHz: frequencies,
      levels: levels,
      sampleRateHz: audio.sampleRateHz,
    );
  }
}
